import "./ripple.js";
import { registerStyles } from "../styles.js";
registerStyles({ "radios": ".mtrl-radios{display:flex;margin:0;padding:0}.mtrl-radios--vertical{flex-direction:column}.mtrl-radios--horizontal{flex-direction:row;flex-wrap:wrap;align-items:flex-start}.mtrl-radios--horizontal .mtrl-radios__item{margin-inline-end:16px}.mtrl-radios--horizontal .mtrl-radios__item:last-child{margin-inline-end:0}.mtrl-radios--disabled{pointer-events:none}.mtrl-radios__item{position:relative;display:inline-flex;align-items:center}.mtrl-radios__item--disabled{cursor:not-allowed}.mtrl-radios__item--disabled .mtrl-radios__label{cursor:not-allowed}.mtrl-radios__input{position:absolute;opacity:0;height:0;width:0;margin:0;padding:0}.mtrl-radios__input:checked~.mtrl-radios__label .mtrl-radios__circle{border-color:var(--mtrl-sys-color-primary)}.mtrl-radios__input:checked~.mtrl-radios__label .mtrl-radios__circle::after{transform:translate(-50%, -50%) scale(1);opacity:1}.mtrl-radios__input:disabled~.mtrl-radios__label .mtrl-radios__circle{border-color:color-mix(in srgb, var(--mtrl-sys-color-on-surface) 38%, transparent)}.mtrl-radios__input:disabled~.mtrl-radios__label .mtrl-radios__circle::after{background-color:color-mix(in srgb, var(--mtrl-sys-color-on-surface) 38%, transparent)}.mtrl-radios__input:disabled~.mtrl-radios__label .mtrl-radios__text{color:color-mix(in srgb, var(--mtrl-sys-color-on-surface) 38%, transparent)}.mtrl-radios__label{position:relative;display:inline-flex;align-items:center;cursor:pointer;padding:4px 0;min-height:48px;color:var(--mtrl-sys-color-on-surface);font-family:var(--mtrl-ref-typeface-plain, Roboto, sans-serif);font-size:16px;line-height:24px;letter-spacing:.5px;font-weight:400}.mtrl-radios__label--before .mtrl-radios__text{margin-inline:0 8px}.mtrl-radios__label:has(>.mtrl-radios__text:empty){min-width:48px;justify-content:center}.mtrl-radios__control{position:relative;display:inline-flex;align-items:center;justify-content:center;width:40px;height:40px;flex-shrink:0}.mtrl-radios__circle{position:relative;width:20px;height:20px;border:2px solid var(--mtrl-sys-color-on-surface-variant);border-radius:50%;box-sizing:border-box;transition:border-color 175ms linear(0, 0.075, 0.227, 0.39, 0.537, 0.657, 0.751, 0.822, 0.874, 0.912, 0.939, 0.958, 0.971, 0.98, 0.987, 0.991, 0.994, 0.996, 0.997, 0.998, 0.999, 0.999, 0.999, 1, 1)}.mtrl-radios__circle::after{content:\"\";position:absolute;top:50%;left:50%;transform:translate(-50%, -50%) scale(0);width:10px;height:10px;border-radius:50%;background-color:var(--mtrl-sys-color-primary);opacity:0;transition:transform 425ms linear(0, 0.102, 0.323, 0.57, 0.784, 0.942, 1.039, 1.085, 1.094, 1.082, 1.06, 1.037, 1.018, 1.004, 0.995, 0.992, 0.991, 0.992, 0.995, 0.997, 0.999, 1, 1.001, 1.001, 1),opacity 175ms linear(0, 0.075, 0.227, 0.39, 0.537, 0.657, 0.751, 0.822, 0.874, 0.912, 0.939, 0.958, 0.971, 0.98, 0.987, 0.991, 0.994, 0.996, 0.997, 0.998, 0.999, 0.999, 0.999, 1, 1)}.mtrl-radios__ripple{position:absolute;inset:0;border-radius:50%;transition:background-color 175ms linear(0, 0.075, 0.227, 0.39, 0.537, 0.657, 0.751, 0.822, 0.874, 0.912, 0.939, 0.958, 0.971, 0.98, 0.987, 0.991, 0.994, 0.996, 0.997, 0.998, 0.999, 0.999, 0.999, 1, 1)}.mtrl-radios__item .mtrl-radios__input:not(:disabled):not(:checked)~.mtrl-radios__label:is(:hover,:active) .mtrl-radios__circle,.mtrl-radios__item .mtrl-radios__input:not(:disabled):not(:checked):focus-visible~.mtrl-radios__label .mtrl-radios__circle{border-color:var(--mtrl-sys-color-on-surface)}.mtrl-radios__item .mtrl-radios__input:not(:disabled)~.mtrl-radios__label:hover .mtrl-radios__ripple{background-color:color-mix(in srgb, var(--mtrl-sys-color-on-surface) 8%, transparent)}.mtrl-radios__item .mtrl-radios__input:not(:disabled):focus-visible~.mtrl-radios__label .mtrl-radios__ripple{background-color:color-mix(in srgb, var(--mtrl-sys-color-on-surface) 10%, transparent)}.mtrl-radios__item .mtrl-radios__input:not(:disabled)~.mtrl-radios__label:active .mtrl-radios__ripple{background-color:color-mix(in srgb, var(--mtrl-sys-color-primary) 10%, transparent)}.mtrl-radios__item .mtrl-radios__input:not(:disabled):checked~.mtrl-radios__label:hover .mtrl-radios__ripple{background-color:color-mix(in srgb, var(--mtrl-sys-color-primary) 8%, transparent)}.mtrl-radios__item .mtrl-radios__input:not(:disabled):checked:focus-visible~.mtrl-radios__label .mtrl-radios__ripple{background-color:color-mix(in srgb, var(--mtrl-sys-color-primary) 10%, transparent)}.mtrl-radios__item .mtrl-radios__input:not(:disabled):checked~.mtrl-radios__label:active .mtrl-radios__ripple{background-color:color-mix(in srgb, var(--mtrl-sys-color-on-surface) 10%, transparent)}.mtrl-radios__item .mtrl-radios__input:not(:disabled):focus-visible~.mtrl-radios__label .mtrl-radios__ripple{outline:3px solid var(--mtrl-sys-color-secondary);outline-offset:2px}.mtrl-radios__text{margin-inline-start:8px}.mtrl-radios__text:empty{display:none}" });
